54	
55	using DependStreamLife = std::map<int32_t, std::map<int64_t, std::map<int64_t, size_t>>>;
56	
57	struct EdgeLife {
58	  size_t node_id;
59	  size_t peer_node_id;
60	};
61	
62	struct CompareEdgeLife {
63	  bool operator()(const ge::EdgeLife &left, const ge::EdgeLife &right) const {
64	    return left.node_id < right.node_id;
65	  }
66	};
67	
68	using DiffStreamEdgeLife = std::map<int64_t, std::map<int64_t, std::set<EdgeLife, CompareEdgeLife>>>;
