72	struct ReuseStrategy {
73	  explicit ReuseStrategy(bool use_range = false, bool ascending_sort = true, bool reuse_first_release = false,
74	                         bool memory_priority_mode = false)
75	      : use_range_(use_range),
76	        ascending_sort_(ascending_sort),
77	        reuse_first_release_(reuse_first_release),
78	        memory_priority_mode_(memory_priority_mode) {}
79	  bool use_range_ = false;
80	  bool ascending_sort_ = true;
81	  bool reuse_first_release_ = false;
82	  bool memory_priority_mode_ = false;
83	};
