103	template <class T>
104	struct TAttr {
105	  TAttr(ge::AttrHolder *const ptr, const ge::OpDesc *const desc, int32_t index, const std::string &name, const T value)
106	      : ptr_(ptr), desc_(desc), name_(name), index_(index), value_(value) {}
107	  ge::AttrHolder *ptr_;
108	  const ge::OpDesc *desc_;
109	  const std::string &name_;
110	  const int32_t index_;
111	  const T value_;
112	};
113	
114	struct NodeTypeIndex {
115	  NodeTypeIndex(const ge::Node *node, OpMemoryType mem_type, uint32_t index, bool ref_input = false, size_t begin = 0,
116	                int64_t stream_id = kInvalidStreamId, bool is_subgraph_workspace = false,
117	                size_t symbol_end_time = kDefaultLifeTime)
118	      : node_(node),
119	        mem_type_(mem_type),
120	        index_(index),
121	        ref_input_(ref_input),
122	        is_subgraph_workspace_(is_subgraph_workspace),
123	        life_time_begin_(begin),
124	        symbol_max_life_time_end_(symbol_end_time),
125	        stream_id_(stream_id) {
126	    if ((node_ != nullptr) && (node_->GetOpDesc() != nullptr)) {
127	      is_subgraph_out_ = (node_->GetOpDesc()->GetType() == ge::PARTITIONEDCALL) && (mem_type_ == OpMemoryType::kOutput);
128	      node_id_ = static_cast<size_t>(node_->GetOpDesc()->GetId());
129	      life_time_begin_is_min_ = (life_time_begin_ > 0) && (life_time_begin_ < node_id_);
130	    } else {
131	      node_id_ = life_time_begin_;
132	    }
133	  }
134	
135	  const std::string GetMemType() const {
136	    return GetMemType(mem_type_);
137	  }
138	  static std::string GetMemType(const OpMemoryType &mem_type) {
139	    switch (mem_type) {
140	      case OpMemoryType::kOutput:
141	        return "output";
142	      case OpMemoryType::kWorkspace:
143	        return "workspace";
144	      case OpMemoryType::kOutputDesc:
145	        return "output_desc";
146	      case OpMemoryType::kInput:
147	        return "input";
148	      default:
149	        return "unknown";
150	    }
151	  }
152	
153	  size_t GetLifeBegin(bool for_sort = false) const {
154	    if (life_time_begin_is_min_) {
155	      return life_time_begin_;
156	    } else {
157	      if (!for_sort && is_subgraph_out_) {
158	        return life_time_end_;
159	      } else {
160	        return node_id_;
161	      }
162	    }
163	  }
164	
165	  std::string GetLifeBeginDesc() const {
166	    if (node_ == nullptr) {
167	      return std::to_string(life_time_begin_);
168	    }
169	
170	    auto life_begin = GetLifeBegin();
171	    if (life_begin != node_id_) {
172	      return std::to_string(life_begin) + "--" + std::to_string(node_id_);
173	    } else {
174	      return std::to_string(life_begin);
175	    }
176	    return "";
177	  }
178	
179	  std::vector<size_t> GetLifeEnd() const {
180	    std::vector<size_t> life_end_list;
181	    bool single_end = true;
182	    for (auto pair : diff_stream_life_time_) {
183	      if (pair.second != life_time_end_) {
184	        life_end_list.emplace_back(pair.second);
185	        single_end = false;
186	      }
187	    }
188	    life_end_list.emplace_back(life_time_end_);
189	    if (single_end && (ref_life_time_end_ != kDefaultLifeTime) && (ref_life_time_end_ != life_time_end_)) {
190	      life_end_list.emplace_back(ref_life_time_end_);
191	    }
192	    return life_end_list;
193	  }
194	
195	  std::string GetLifeEndDesc() const {
196	    std::string end_desc;
197	    const auto life_end_list = GetLifeEnd();
198	    for (const auto life_end : life_end_list) {
199	      if (!end_desc.empty()) {
200	        end_desc.append("--");
201	      }
202	      end_desc.append(std::to_string(life_end));
203	    }
204	    return end_desc;
205	  }
206	
207	  void SetOutStreamCount(size_t count) {
208	    if (count > out_stream_count_) {
209	      out_stream_count_ = count;
210	    }
211	  }
212	  void SetFirstContinuousNode(const bool flag) {
213	    first_continuous_node_ = flag;
214	  }
215	  void SetLastContinuousNode(const bool flag) {
216	    last_continuous_node_ = flag;
217	  }
218	  void SetContinuousNode(const bool flag) {
219	    continuous_node_ = flag;
220	  }
221	  bool GetFirstContinuousNodeFlag() const {
222	    return first_continuous_node_;
223	  }
224	  bool GetLastContinuousNodeFlag() const {
225	    return last_continuous_node_;
226	  }
227	  bool GetContinuousNodeFlag() const {
228	    return continuous_node_;
229	  }
