231	  const ge::Node *node_ = nullptr;
232	  OpMemoryType mem_type_ = OpMemoryType::kOutput;
233	  uint32_t index_ = 0;
234	  bool ref_input_ = false;
235	  bool is_subgraph_workspace_ = false;
236	  bool is_subgraph_out_ = false;
237	  bool life_time_begin_is_min_ = false;
238	  bool next_is_ref_input_ = false;
239	  size_t life_time_begin_ = 0;
240	  size_t life_time_end_ = kDefaultLifeTime;
241	  size_t symbol_max_life_time_end_ = kDefaultLifeTime;
242	  int64_t stream_id_ = kInvalidStreamId;
243	  size_t node_id_ = 0U;
244	  std::map<int64_t, size_t> diff_stream_life_time_;
245	  std::map<int64_t, std::pair<size_t, size_t>> out_stream_life_time_;
246	  size_t ref_life_time_end_ = kDefaultLifeTime;
247	  size_t out_stream_count_ = 1U;
248	  size_t no_align_size_ = 0U;
249	  bool continuous_node_ = false;
250	  bool first_continuous_node_ = false;
251	  bool last_continuous_node_ = false;
252	};
