254	class BlockMemAssigner;
255	class MemoryBlock {
256	 public:
257	  explicit MemoryBlock(const ReuseStrategy &reuse_strategy, size_t block_size, int64_t stream_id = 0,
258	                       bool reuse_mem = true, uint64_t memory_type = RT_MEMORY_HBM)
259	      : ref_count_(0),
260	        stream_id_(stream_id),
261	        child_block_(false),
262	        reuse_mem_(reuse_mem),
263	        same_stream_(true),
264	        has_sub_graph_in_out_node_(false),
265	        input_index_(0),
266	        continuous_block_(false),
267	        first_continuous_block_(false),
268	        last_continuous_block_(false),
269	        is_zero_copy_(false),
270	        is_reuse_zero_copy_(true),
271	        memory_type_(memory_type),
272	        memory_type_logic_base_(0),
273	        need_same_offset_in_batch_(false),
274	        max_real_size_(0),
275	        max_block_size_(0),
276	        window_size_(1U),
277	        thread_dim_(1U),
278	        post_reuse_flag_(true),
279	        is_fixed_addr_prior_(false),
280	        diff_stream_prior_(false),
281	        used_by_diff_streams_(false),
282	        block_size_(block_size),
283	        head_offset_(0U),
284	        tail_offset_(0U),
285	        child_offset_(0U),
286	        batch_used_size_(0U),
287	        reuse_strategy_(reuse_strategy) {
288	    switch (memory_type_) {
289	      case RT_MEMORY_HOST:
290	        memory_type_logic_base_ = kMemoryHostFeatureMapLogicBase;
291	        break;
292	      case RT_MEMORY_HOST_SVM:
293	        memory_type_logic_base_ = kMemoryHostSVMFeatureMapLogicBase;
294	        break;
295	      default:
296	        break;
297	    }
298	  }
299	
300	  MemoryBlock(const MemoryBlock &) = delete;
301	
302	  MemoryBlock &operator=(const MemoryBlock &) = delete;
303	
304	  ~MemoryBlock() {
305	    node_type_index_list_.clear();
306	    symbol_list_.clear();
307	  }
308	
309	  size_t Size() const {
310	    return block_size_;
311	  }
312	
313	  void SetSize(size_t size) {
314	    if (size > block_size_) {
315	      block_size_ = size;
316	    }
317	  }
318	
319	  size_t AlignSize();
320	
321	  Status SetHeadOffset(size_t offset);
322	
323	  void SetTailOffset(size_t offset);
324	
325	  size_t HeadOffset() const {
326	    return head_offset_;
327	  }
328	
329	  size_t TailOffset() const {
330	    return tail_offset_;
331	  }
332	
333	  void AddNodeTypeIndex(const NodeTypeIndex &node_type_index, size_t real_size, size_t no_align_size,
334	                        int64_t stream_id) {
335	    if (node_type_index.ref_input_) {
336	      if (!node_type_index_list_.empty()) {
337	        node_type_index_list_.back().next_is_ref_input_ = true;
338	      }
339	    }
340	    node_type_index_list_.emplace_back(node_type_index);
341	    node_type_index_list_.back().no_align_size_ = no_align_size;
342	    real_size_list_.emplace_back(real_size);
343	    no_align_size_list_.emplace_back(no_align_size);
344	
345	    if (stream_id != stream_id_) {
346	      same_stream_ = false;
347	    }
348	
349	    // need recompute max real size
350	    max_real_size_ = 0;
351	    last_continuous_block_ = last_continuous_block_ || node_type_index.GetLastContinuousNodeFlag();
352	    first_continuous_block_ = first_continuous_block_ || node_type_index.GetFirstContinuousNodeFlag();
353	    continuous_block_ = continuous_block_ || node_type_index.GetContinuousNodeFlag();
354	    block_type_list_.WithAdded(node_type_index);
355	  }
356	
357	  bool IsBlockTypeConflict(const MemoryBlock &other) const {
358	    return block_type_list_.IsConflictWithBlock(other.block_type_list_);
359	  }
360	
361	  bool IsBlockTypeConflictWithNode(const NodeTypeIndex &node_type_index) const {
362	    return block_type_list_.IsConflictWithOneNode(node_type_index);
363	  }
364	
365	  std::string BlockTypeStr() const {
366	    return block_type_list_.ToString();
367	  }
