391	    return child_blocks_;
392	  }
393	  const std::map<std::string, std::vector<MemoryBlock *>> &BatchBlockList() const {
394	    return batch_to_blocks_;
395	  }
396	  const std::vector<size_t> &NoAlignSizeList() const {
397	    return no_align_size_list_;
398	  }
399	  const std::vector<MemoryBlock *> &ChildSubGraphBlockList() const {
400	    return sub_graph_blocks_;
401	  }
402	  bool IsNoAlignSizeReuseBlock() const {
403	    return continuous_block_;
404	  }
405	  bool IsRealSizeReuseBlock() const {
406	    return is_zero_copy_;
407	  }
408	  std::vector<MemoryBlock *> AllChildBlockList() const;
409	
410	  inline void SetRefLifeTimeEnd() {
411	    for (size_t index = 0U; index < node_type_index_list_.size(); ++index) {
412	      auto &node_type_index = node_type_index_list_[index];
413	      if (!node_type_index.next_is_ref_input_ || node_type_index.ref_input_) {
414	        continue;
415	      }
416	      size_t ref_end_index = index;
417	      for (size_t i = index + 1U; i < node_type_index_list_.size(); ++i) {
418	        if (!node_type_index_list_[i].ref_input_) {
419	          break;
420	        }
421	        ref_end_index = i;
422	      }
423	      node_type_index.ref_life_time_end_ = node_type_index_list_[ref_end_index].life_time_end_;
424	    }
425	  }
